import sys, io, json, os, contextlib, glob
pkg=sys.argv[1]; sys.path.insert(0,pkg)
from meterbill import cli
out={}
def run(argv):
    o,e=io.StringIO(),io.StringIO()
    with contextlib.redirect_stdout(o), contextlib.redirect_stderr(e):
        try: rc=cli.main(argv)
        except SystemExit as x: rc=('exit',x.code)
        except BaseException as x: rc=('exc',type(x).__name__)
    return [rc,o.getvalue(),e.getvalue()]
for i in range(400):
    d=f'/tmp/fz/cases/{i}'; b=['--tariffs',d+'/book.json']
    for f in sorted(glob.glob(d+'/acc/*.json')):
        for fmt in ('text','csv','json'): out[f'{f}{fmt}']=run(b+['bill',f,'--format',fmt])
    for fmt in ('text','csv'):
        for w in ('1','3'): out[f'{d}b{fmt}{w}']=run(b+['batch',d+'/acc','--format',fmt,'--workers',w])
    out[d+'t']=run(b+['tariffs'])
    import random; random.seed(i)
    for t in ('t0','t1','t2'):
        for _ in range(4):
            k=random.choice(['0','1','5','100.5','250.125','300.5','0.005','1234.567','99999.9999', '0.5','3.5','2.5']); dd=str(random.randint(1,100))
            for fmt in ('text','json'): out[f'{d}q{t}{k}{dd}{fmt}']=run(b+['quote',t,k,dd,'--format',fmt])
json.dump(out,open(sys.argv[2],'w'),sort_keys=True)
